          "code": "import numpy as np\nfrom sklearn.linear_model import LinearRegression, PoissonRegressor\nfrom sklearn.metrics import mean_poisson_deviance\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(42)\nn = 1500\n# Fitur polis kendaraan: usia pengemudi (std), tenaga mesin (std), densitas kota (std)\nX = rng.normal(0.0, 1.0, size=(n, 3))\n# 25% polis baru berdurasi singkat (0.04 - 0.15 tahun), sisanya hingga 1.0 tahun\nshort_mask = rng.random(n) < 0.25\nexposure = np.where(short_mask, rng.uniform(0.04, 0.15, n), rng.uniform(0.30, 1.0, n))\n\nrate_true = np.exp(-0.70 - 0.45 * X[:, 0] + 0.65 * X[:, 1] + 0.35 * X[:, 2])\nclaims = rng.poisson(exposure * rate_true).astype(float)\nrate_obs = claims / exposure\n\nX_tr, X_te, r_tr, r_te, c_tr, c_te, e_tr, e_te = train_test_split(\n    X, rate_obs, claims, exposure, test_size=0.30, random_state=42\n)\n\n# 1. ANTI-PATTERN: OLS langsung pada y / exposure tanpa bobot\nols_bad = LinearRegression().fit(X_tr, r_tr)\nrate_pred_ols = ols_bad.predict(X_te)\nclaims_pred_ols = rate_pred_ols * e_te\nn_neg_ols = int(np.sum(rate_pred_ols < 0.0))\n\n# 2. SETENGAH BENAR (TETAP BUG): PoissonRegressor pada y / exposure TANPA sample_weight\npois_unw = PoissonRegressor(alpha=0.0, max_iter=500).fit(X_tr, r_tr)\nrate_pred_unw = pois_unw.predict(X_te)\nclaims_pred_unw = rate_pred_unw * e_te\n\n# 3. PRODUCTION-SAFE: PoissonRegressor pada y / exposure DENGAN sample_weight=exposure\npois_safe = PoissonRegressor(alpha=0.0, max_iter=500).fit(X_tr, r_tr, sample_weight=e_tr)\nrate_pred_safe = pois_safe.predict(X_te)\nclaims_pred_safe = rate_pred_safe * e_te\n\nprint(f\"Max rate mentah polis durasi pendek di Train : {float(np.max(r_tr)):.2f} klaim/tahun\")\nprint(f\"Total klaim aktual pada Test Set             : {float(np.sum(c_te)):.1f}\")\nprint(\"Pendekatan Model                  | Pred<0 | Total Pred | Bias %  | Weighted Pois Dev\")\nprint(\"-\" * 85)\nfor name, r_pred, c_pred, neg_cnt in [\n    (\"1. OLS pada y/exposure (BUG)     \", rate_pred_ols, claims_pred_ols, n_neg_ols),\n    (\"2. Poisson tanpa sample_weight   \", rate_pred_unw, claims_pred_unw, 0),\n    (\"3. Poisson + sample_weight=E     \", rate_pred_safe, claims_pred_safe, 0),\n]:\n    tot_p = float(np.sum(c_pred))\n    bias_pct = 100.0 * (tot_p - float(np.sum(c_te))) / float(np.sum(c_te))\n    if neg_cnt > 0:\n        dev_str = \"INVALID (<0)\"\n    else:\n        dev_v = float(mean_poisson_deviance(r_te, r_pred, sample_weight=e_te))\n        dev_str = f\"{dev_v:17.4f}\"\n    print(f\"{name:33s} | {neg_cnt:6d} | {tot_p:10.1f} | {bias_pct:+6.2f}% | {dev_str:>17s}\")",
