          "id": "code-ml-09-2-ch09_2_diag",
          "title": "Diagnostik Overdispersion: Pearson Chi2/df & Coverage Interval 95% (Pois vs NB2)",
          "language": "python",
          "filename": "09_2_overdispersion_coverage_audit.py",
          "code": "import numpy as np\nfrom scipy.stats import nbinom, poisson\nfrom sklearn.linear_model import PoissonRegressor\n\nrng = np.random.default_rng(42)\nn_tr, n_te = 1000, 500\nX_tr = rng.normal(0.0, 1.0, size=(n_tr, 2))\nX_te = rng.normal(0.0, 1.0, size=(n_te, 2))\nmu_tr_true = np.exp(1.1 + 0.5 * X_tr[:, 0] - 0.4 * X_tr[:, 1])\nmu_te_true = np.exp(1.1 + 0.5 * X_te[:, 0] - 0.4 * X_te[:, 1])\n\nprint(\"=== Audit Coverage Interval Prediksi 95%: Poisson vs Negative Binomial (NB2) ===\")\nprint(\"Skenario Data          | Pearson Chi2/df | alpha_MoM | Cov95% Poisson | Cov95% NB2\")\nprint(\"-\" * 84)\nfor label, alpha_true in [\n    (\"Equidispersed (Pois)  \", 0.0),\n    (\"Overdispersed (a=0.4) \", 0.4),\n    (\"Heavy Overdisp (a=1.2)\", 1.2),\n]:\n    if alpha_true == 0.0:\n        y_tr = rng.poisson(mu_tr_true).astype(float)\n        y_te = rng.poisson(mu_te_true).astype(float)\n    else:\n        r_shape = 1.0 / alpha_true\n        y_tr = rng.poisson(rng.gamma(r_shape, alpha_true * mu_tr_true)).astype(float)\n        y_te = rng.poisson(rng.gamma(r_shape, alpha_true * mu_te_true)).astype(float)\n\n    mdl = PoissonRegressor(alpha=0.0, max_iter=500).fit(X_tr, y_tr)\n    mu_tr_hat = mdl.predict(X_tr)\n    mu_te_hat = mdl.predict(X_te)\n\n    # Estimasi dispersi Pearson & Method-of-Moments alpha NB2: E[(y-mu)^2 - mu] = alpha * mu^2\n    phi_hat = float(np.sum(((y_tr - mu_tr_hat) ** 2) / mu_tr_hat) / (n_tr - 3))\n    alpha_mom = max(\n        0.0,\n        float(np.sum((y_tr - mu_tr_hat) ** 2 - mu_tr_hat) / np.sum(mu_tr_hat ** 2)),\n    )\n\n    # 95% Prediction Interval di bawah asumsi Poisson murni\n    lo_p, hi_p = poisson.ppf(0.025, mu_te_hat), poisson.ppf(0.975, mu_te_hat)\n    cov_p = float(np.mean((y_te >= lo_p) & (y_te <= hi_p)))\n\n    # 95% Prediction Interval di bawah Negative Binomial NB2 (n=1/alpha, p=n/(n+mu))\n    if alpha_mom < 1e-4:\n        lo_nb, hi_nb = lo_p, hi_p\n    else:\n        r_hat = 1.0 / alpha_mom\n        p_nb = r_hat / (r_hat + mu_te_hat)\n        lo_nb, hi_nb = nbinom.ppf(0.025, r_hat, p_nb), nbinom.ppf(0.975, r_hat, p_nb)\n    cov_nb = float(np.mean((y_te >= lo_nb) & (y_te <= hi_nb)))\n\n    print(f\"{label:22s} | {phi_hat:15.3f} | {alpha_mom:9.3f} | {cov_p*100:13.1f}% | {cov_nb*100:9.1f}%\")",
