          "id": "code-ml-09-4-ch09_4_scratch",
          "title": "First-Principles NumPy: Unit Deviance, Normalized Gini & Balance Property",
          "language": "python",
          "filename": "09_4_deviance_gini_balance_scratch.py",
          "code": "import numpy as np\nfrom sklearn.linear_model import GammaRegressor, PoissonRegressor, TweedieRegressor\n\ndef tweedie_unit_deviance(y: np.ndarray, mu: np.ndarray, p: float) -> np.ndarray:\n    y = np.asarray(y, dtype=float)\n    mu = np.maximum(np.asarray(mu, dtype=float), 1e-12)\n    if abs(p) < 1e-9:\n        return (y - mu) ** 2\n    if abs(p - 1.0) < 1e-9:\n        t1 = np.where(y > 0.0, y * np.log(np.maximum(y, 1e-12) / mu), 0.0)\n        return 2.0 * (t1 - (y - mu))\n    if abs(p - 2.0) < 1e-9:\n        return 2.0 * (np.log(mu / np.maximum(y, 1e-12)) + (y - mu) / mu)\n    t1 = np.where(y > 0.0, (y ** (2.0 - p)) / ((1.0 - p) * (2.0 - p)), 0.0)\n    t2 = (y * (mu ** (1.0 - p))) / (1.0 - p)\n    t3 = (mu ** (2.0 - p)) / (2.0 - p)\n    return 2.0 * (t1 - t2 + t3)\n\ndef normalized_gini(y_true: np.ndarray, y_pred: np.ndarray, w: np.ndarray) -> float:\n    \"\"\"Normalized Gini (Ordered Lorenz Curve): 1.0 = pemeringkatan risiko sempurna.\"\"\"\n    def raw_gini(yt, yp, wt):\n        order = np.argsort(yp)\n        y_s, w_s = yt[order], wt[order]\n        cum_w = np.cumsum(w_s) / np.sum(w_s)\n        cum_y = np.cumsum(y_s * w_s) / np.sum(y_s * w_s)\n        area = float(np.trapezoid(cum_y, cum_w))\n        return 1.0 - 2.0 * area\n    return raw_gini(y_true, y_pred, w) / max(raw_gini(y_true, y_true, w), 1e-12)\n\nrng = np.random.default_rng(42)\nn = 1200\nX = rng.normal(0.0, 1.0, size=(n, 3))\nw = rng.uniform(0.2, 1.0, size=n)\n\n# 1. Poisson (Canonical Log-Link -> EXACT Balance Property!)\nmu_p_true = np.exp(-0.4 + 0.55 * X[:, 0] - 0.35 * X[:, 1])\ny_p = rng.poisson(w * mu_p_true).astype(float) / w\nm_pois = PoissonRegressor(alpha=0.0, max_iter=500, tol=1e-9).fit(X, y_p, sample_weight=w)\nmu_p_hat = m_pois.predict(X)\n\n# 2. Gamma (Non-Canonical Log-Link -> Rata-rata rasio y/mu = 1, bukan exact sum balance!)\nmu_g_true = np.exp(5.0 + 0.65 * X[:, 0] - 0.50 * X[:, 1] + 0.30 * X[:, 2])\ny_g = rng.gamma(shape=2.2, scale=mu_g_true / 2.2)\nm_gam = GammaRegressor(alpha=0.0, max_iter=500, tol=1e-9).fit(X, y_g, sample_weight=w)\nmu_g_hat = m_gam.predict(X)\n\n# 3. Tweedie p=1.5 (Non-Canonical Log-Link dengan regularisasi alpha=0.5)\ny_tw = np.where(rng.random(n) < 0.72, 0.0, y_g)\nm_tw = TweedieRegressor(power=1.5, alpha=0.5, max_iter=500).fit(X, y_tw, sample_weight=w)\nmu_tw_hat = m_tw.predict(X)\n\nprint(\"=== Audit Balance Property (sum w*mu vs sum w*y) & First-Order Score ===\")\nfor name, yt, mh, wt, p_val in [\n    (\"Poisson (p=1, Canonical Log)  \", y_p, mu_p_hat, w, 1.0),\n    (\"Gamma (p=2, Non-Canonical Log)\", y_g, mu_g_hat, w, 2.0),\n    (\"Tweedie (p=1.5, L2 alpha=0.5) \", y_tw, mu_tw_hat, w, 1.5),\n]:\n    sum_y = float(np.sum(wt * yt))\n    sum_m = float(np.sum(wt * mh))\n    ae_ratio = sum_y / sum_m\n    d_mod = float(np.average(tweedie_unit_deviance(yt, mh, p_val), weights=wt))\n    y_bar = float(np.average(yt, weights=wt))\n    d_null = float(np.average(tweedie_unit_deviance(yt, np.full(n, y_bar), p_val), weights=wt))\n    d2 = 1.0 - d_mod / d_null\n    gini = normalized_gini(yt, mh, wt)\n    print(f\"{name} | A/E={ae_ratio:.5f} | D^2={d2:.4f} | NormGini={gini:.4f}\")\n\n# Verifikasi kondisi skor intercept eksak Gamma Log-Link: sum w_i * (y_i - mu_i) / mu_i == 0\ngamma_intercept_score = float(np.sum(w * (y_g - mu_g_hat) / mu_g_hat) / np.sum(w))\n# Pulihkan balance Gamma lewat multiplicative shift c = sum(w*y)/sum(w*mu)\nc_cal = float(np.sum(w * y_g) / np.sum(w * mu_g_hat))\nmu_g_cal = c_cal * mu_g_hat\nprint(f\"Gamma Log-Link mean((y - mu)/mu) = {gamma_intercept_score:+.2e} (tepat nol, tapi A/E != 1)\")\nprint(f\"Setelah Recalibration c={c_cal:.5f} -> A/E={float(np.sum(w*y_g)/np.sum(w*mu_g_cal)):.5f} | Gini tetap={normalized_gini(y_g, mu_g_cal, w):.4f}\")",
          "expectedOutput": "=== Audit Balance Property (sum w*mu vs sum w*y) & First-Order Score ===\nPoisson (p=1, Canonical Log)   | A/E=1.00000 | D^2=0.1896 | NormGini=0.4821\nGamma (p=2, Non-Canonical Log) | A/E=0.98678 | D^2=0.6023 | NormGini=0.8158\nTweedie (p=1.5, L2 alpha=0.5)  | A/E=0.99868 | D^2=0.0920 | NormGini=0.4149\nGamma Log-Link mean((y - mu)/mu) = -3.96e-10 (tepat nol, tapi A/E != 1)\nSetelah Recalibration c=0.98678 -> A/E=1.00000 | Gini tetap=0.8158",
          "actualOutput": "=== Audit Balance Property (sum w*mu vs sum w*y) & First-Order Score ===\nPoisson (p=1, Canonical Log)   | A/E=1.00000 | D^2=0.1896 | NormGini=0.4821\nGamma (p=2, Non-Canonical Log) | A/E=0.98678 | D^2=0.6023 | NormGini=0.8158\nTweedie (p=1.5, L2 alpha=0.5)  | A/E=0.99868 | D^2=0.0920 | NormGini=0.4149\nGamma Log-Link mean((y - mu)/mu) = -3.96e-10 (tepat nol, tapi A/E != 1)\nSetelah Recalibration c=0.98678 -> A/E=1.00000 | Gini tetap=0.8158",
