          "filename": "09_4_oot_portfolio_calibration_lift.py",
          "code": "import numpy as np\nfrom sklearn.linear_model import TweedieRegressor\nfrom sklearn.metrics import d2_tweedie_score\n\nrng = np.random.default_rng(42)\nn_tr, n_oot = 1200, 1400\nX_tr = rng.normal(0.0, 1.0, size=(n_tr, 3))\nX_oot = rng.normal(0.0, 1.0, size=(n_oot, 3))\nw_tr = rng.uniform(0.4, 1.0, size=n_tr)\nw_oot = rng.uniform(0.4, 1.0, size=n_oot)\n\n# Data latih (Tahun 1) vs Out-of-Time (Tahun 2 dengan inflasi biaya klaim +12%!)\nmu_tr = np.exp(4.5 + 0.55 * X_tr[:, 0] - 0.40 * X_tr[:, 1] + 0.25 * X_tr[:, 2])\nmu_oot = 1.12 * np.exp(4.5 + 0.55 * X_oot[:, 0] - 0.40 * X_oot[:, 1] + 0.25 * X_oot[:, 2])\n\ndef sim_tw(mu_v, w_v, p=1.5, phi=4.0):\n    lam = (w_v * (mu_v ** (2.0 - p))) / (phi * (2.0 - p))\n    cnt = rng.poisson(lam)\n    y_tot = np.zeros(len(mu_v))\n    pos = cnt > 0\n    y_tot[pos] = rng.gamma(shape=cnt[pos], scale=phi * (p - 1.0) * (mu_v[pos] ** (p - 1.0)))\n    return y_tot / w_v\n\ny_tr = sim_tw(mu_tr, w_tr)\ny_oot = sim_tw(mu_oot, w_oot)\n\nmdl = TweedieRegressor(power=1.5, alpha=0.05, max_iter=500).fit(X_tr, y_tr, sample_weight=w_tr)\npred_raw = mdl.predict(X_oot)\n\n# Kalibrasi Balance Portofolio dari jendela kalibrasi terbaru (500 polis awal OOT) -> uji di 900 sisa OOT\ncal_n = 500\nc_balance = float(np.sum(w_oot[:cal_n] * y_oot[:cal_n]) / np.sum(w_oot[:cal_n] * pred_raw[:cal_n]))\ny_eval, w_eval = y_oot[cal_n:], w_oot[cal_n:]\npred_eval_raw = pred_raw[cal_n:]\npred_eval_cal = c_balance * pred_eval_raw\n\nprint(\"=== Audit Kalibrasi Portofolio Out-of-Time (Inflasi Klaim +12%) ===\")\nprint(f\"Faktor Multiplicative Balance Recalibration (dari 500 polis awal): c = {c_balance:.4f}\")\nprint(f\"Global A/E Ratio -> Raw={np.sum(w_eval*y_eval)/np.sum(w_eval*pred_eval_raw):.4f} | \"\n      f\"Recalibrated={np.sum(w_eval*y_eval)/np.sum(w_eval*pred_eval_cal):.4f}\")\nprint(f\"Test D^2 (p=1.5) -> Raw={d2_tweedie_score(y_eval, pred_eval_raw, power=1.5, sample_weight=w_eval):.4f} | \"\n      f\"Recalibrated={d2_tweedie_score(y_eval, pred_eval_cal, power=1.5, sample_weight=w_eval):.4f}\")\n\n# Tabel Lift Kalibrasi per Kuintil Risiko (5 Kelompok)\nqs = np.quantile(pred_eval_cal, np.linspace(0.0, 1.0, 6))\nprint(\"Kuintil Risiko | Mean Actual | Raw Pred | Calib Pred | A/E Raw | A/E Calib\")\nprint(\"-\" * 76)\nfor k in range(5):\n    lo, hi = qs[k], qs[k + 1]\n    mask = (pred_eval_cal >= lo) & (pred_eval_cal <= hi if k == 4 else pred_eval_cal < hi)\n    act_m = float(np.average(y_eval[mask], weights=w_eval[mask]))\n    raw_m = float(np.average(pred_eval_raw[mask], weights=w_eval[mask]))\n    cal_m = float(np.average(pred_eval_cal[mask], weights=w_eval[mask]))\n    print(f\"Q{k+1} ({int(np.sum(mask)):3d} polis)| {act_m:11.2f} | {raw_m:8.2f} | {cal_m:10.2f} | {act_m/raw_m:7.3f} | {act_m/cal_m:9.3f}\")",
          "expectedOutput": "=== Audit Kalibrasi Portofolio Out-of-Time (Inflasi Klaim +12%) ===\nFaktor Multiplicative Balance Recalibration (dari 500 polis awal): c = 1.1213\nGlobal A/E Ratio -> Raw=1.1333 | Recalibrated=1.0107\nTest D^2 (p=1.5) -> Raw=0.4664 | Recalibrated=0.4816\nKuintil Risiko | Mean Actual | Raw Pred | Calib Pred | A/E Raw | A/E Calib\n----------------------------------------------------------------------------\nQ1 (180 polis)|       40.75 |    36.48 |      40.91 |   1.117 |     0.996\nQ2 (180 polis)|       75.90 |    64.37 |      72.18 |   1.179 |     1.052\nQ3 (180 polis)|      108.95 |    94.60 |     106.07 |   1.152 |     1.027\nQ4 (180 polis)|      162.50 |   141.49 |     158.66 |   1.148 |     1.024\nQ5 (180 polis)|      307.68 |   276.63 |     310.19 |   1.112 |     0.992",
